import React from 'react';

export default function Timetable({ onTeacherClick }) {
  const classes = [
    { grade: "Grade 11", subject: "Mathematics", time: "Monday 4.00 PM", teacher: "නලින්ද ජයසිංහ" },
    { grade: "Grade 11", subject: "Commerce", time: "Tuesday 2.30 PM", teacher: "චාමර සර්" },
    { grade: "A/L 2026", subject: "Accounting", time: "Friday 8.00 AM", teacher: "ප්‍රසිද්ධ දිසානායක" },
    { grade: "A/L 2026", subject: "Business Studies", time: "Thursday 8.00 AM", teacher: "චාමර සර්" },
    { grade: "A/L 2026", subject: "Physics", time: "Friday 8.00 AM", teacher: "මනෝජ් සර්" },
    { grade: "Grade 6", subject: "Mathematics", time: "Monday 3.00 PM", teacher: "බුද්ධිකා දර්ශනී" }
  ];

  return (
    <div style={{ padding: '60px 20px', maxWidth: '1200px', margin: '0 auto' }}>
      <h2 style={{ textAlign: 'center', color: '#1e3a8a', marginBottom: '40px' }}>Our Class Schedule</h2>
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(280px, 1fr))', gap: '20px' }}>
        {classes.map((item, idx) => (
          <div key={idx} style={{ backgroundColor: '#fff', padding: '25px', borderRadius: '15px', boxShadow: '0 4px 12px rgba(0,0,0,0.05)', borderLeft: '6px solid #0056b3' }}>
            <span style={{ fontSize: '12px', fontWeight: 'bold', color: '#0056b3', textTransform: 'uppercase' }}>{item.grade}</span>
            <h3 style={{ margin: '10px 0', fontSize: '20px' }}>{item.subject}</h3>
            <p style={{ color: '#666', fontSize: '14px', marginBottom: '15px' }}>⏰ {item.time}</p>
            <div style={{ borderTop: '1px solid #eee', paddingTop: '15px' }}>
              <span style={{ fontSize: '13px', color: '#888' }}>Lecturer:</span> <br/>
              <span onClick={onTeacherClick} style={{ color: '#059669', fontWeight: 'bold', cursor: 'pointer', textDecoration: 'underline' }}>{item.teacher}</span>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}
